<?php
require __DIR__.'/bootstrap.php';
$u=require_admin();$ok=flash('ok');
$total=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
$subs=(int)$pdo->query("SELECT COUNT(*) FROM subscriptions WHERE status IN ('trial','active')")->fetchColumn();
$vids=(int)$pdo->query("SELECT COUNT(*) FROM exclusive_videos WHERE status='published'")->fetchColumn();
$docs=(int)$pdo->query("SELECT COUNT(*) FROM private_documents WHERE status='published'")->fetchColumn();
$open=(int)$pdo->query("SELECT COUNT(*) FROM support_tickets WHERE status!='closed'")->fetchColumn();
$income=(float)$pdo->query("SELECT COALESCE(SUM(p.monthly_price),0) FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.status IN ('trial','active')")->fetchColumn();
$users=$pdo->query("SELECT u.name,p.name plan,s.started_at,s.status FROM users u LEFT JOIN subscriptions s ON s.user_id=u.id LEFT JOIN plans p ON p.id=s.plan_id ORDER BY u.id DESC LIMIT 5")->fetchAll();
$videos=$pdo->query("SELECT * FROM exclusive_videos WHERE status='published' ORDER BY id DESC LIMIT 3")->fetchAll();
